 [StructLayout(LayoutKind.Explicit,Size=32)] struct CapsEx { [FieldOffset(20)] public ushort vendor; [FieldOffset(22)] public ushort product; [FieldOffset(24)] public ushort revision; }
 [DllImport("xinput1_4.dll",EntryPoint="#108",ExactSpelling=true)] static extern uint XInputGetCapabilitiesEx(uint reserved,uint slot,uint flags,out CapsEx caps);
 static CapsEx Identity(uint slot){CapsEx caps;if(XInputGetCapabilitiesEx(1,slot,0,out caps)!=0)throw new Exception("Cannot identify the physical XInput source. Reconnect and detect the source again.");return caps;}
 static bool PhysicalIdentity(CapsEx actual,ushort vendor,ushort product){return actual.vendor==0x3537&&actual.vendor==vendor&&actual.product==product;}
 static void RequirePhysical(uint slot,ushort vendor,ushort product){if(!PhysicalIdentity(Identity(slot),vendor,product))throw new Exception("The selected XInput source changed or is a virtual controller. Playback stopped to prevent feedback.");}
 class Command { public int[] codes=new int[0], blocked=new int[0], keys=new int[0], mouse=new int[0]; }
 static readonly object gate=new object(); static Command command=new Command(); static volatile bool stopped,commandReceived; static long lastCommand; static readonly JavaScriptSerializer json=new JavaScriptSerializer();
 static HashSet<int> keys=new HashSet<int>(),mouse=new HashSet<int>();
 static void Check(uint code) { if(code!=0x20000000)throw new Exception("ViGEm error 0x"+code.ToString("X8")); }
 static void Send(Input i) { if(SendInput(1,new[]{i},Marshal.SizeOf(typeof(Input)))!=1)throw new Exception("Windows denied keyboard/mouse playback. Release attempted; check app/game permissions."); }
 static void Key(int k,bool down) { Send(new Input{type=1,vk=(ushort)k,keyFlags=(down?0u:2u)|((k>=33&&k<=46||k==163||k==165||k==91||k==111||k==144)?1u:0u)}); }
 static void Mouse(int k,bool down) { uint f=0,d=0;switch(k){case 200:f=down?2u:4u;break;case 201:f=down?32u:64u;break;case 202:f=down?8u:16u;break;case 203:f=down?128u:256u;d=2;break;case 204:f=down?128u:256u;d=1;break;case 205:if(!down)return;f=2048;d=120;break;case 206:if(!down)return;f=2048;d=unchecked((uint)-120);break;}if(f!=0)Send(new Input{type=0,mouseFlags=f,data=d}); }
 static void UpdateKeys(Command c){var next=new HashSet<int>(c.keys);foreach(var k in new List<int>(keys))if(!next.Contains(k)){Key(k,false);keys.Remove(k);}foreach(var k in next)if(!keys.Contains(k)){keys.Add(k);Key(k,true);}var m=new HashSet<int>(c.mouse);foreach(var k in new List<int>(mouse))if(!m.Contains(k)){Mouse(k,false);mouse.Remove(k);}foreach(var k in m)if(!mouse.Contains(k)){mouse.Add(k);Mouse(k,true);}}
 static int Mask(int k){switch(k){case 1:return 1;case 2:return 2;case 3:return 4;case 4:return 8;case 5:return 256;case 6:return 512;case 7:return 64;case 8:return 128;case 9:return 4096;case 10:return 8192;case 11:return 16384;case 12:return 32768;case 13:return 1024;case 14:return 32;case 15:return 16;}return 0;}
 static Pad Mix(Pad p,Command c){foreach(int k in c.blocked){p.buttons=(ushort)(p.buttons&~Mask(k));switch(k){case 19:p.lt=0;break;case 20:p.rt=0;break;case 21:if(p.ly>0)p.ly=0;break;case 22:if(p.ly<0)p.ly=0;break;case 23:if(p.lx<0)p.lx=0;break;case 24:if(p.lx>0)p.lx=0;break;case 25:if(p.ry>0)p.ry=0;break;case 26:if(p.ry<0)p.ry=0;break;case 27:if(p.rx<0)p.rx=0;break;case 28:if(p.rx>0)p.rx=0;break;}}
 foreach(int k in c.codes){p.buttons|=(ushort)Mask(k);switch(k){case 19:p.lt=255;break;case 20:p.rt=255;break;case 21:p.ly=32767;break;case 22:p.ly=-32768;break;case 23:p.lx=-32768;break;case 24:p.lx=32767;break;case 25:p.ry=32767;break;case 26:p.ry=-32768;break;case 27:p.rx=-32768;break;case 28:p.rx=32767;break;}}return p;}


 [DllImport("cfgmgr32.dll",CharSet=CharSet.Unicode)] static extern uint CM_Locate_DevNodeW(out uint node,string id,uint flags);
 [DllImport("cfgmgr32.dll")] static extern uint CM_Get_Parent(out uint parent,uint child,uint flags);
 [DllImport("cfgmgr32.dll",CharSet=CharSet.Unicode)] static extern uint CM_Get_Device_IDW(uint node,StringBuilder id,uint length,uint flags);
 static string[] DeviceParents(string id){uint node;if(CM_Locate_DevNodeW(out node,id,0)!=0)throw new Exception("Gamepad device instance not found");var result=new List<string>();for(int i=0;i<16;i++){var name=new StringBuilder(512);if(CM_Get_Device_IDW(node,name,512,0)!=0)throw new Exception("Cannot read controller ancestry");result.Add(name.ToString());uint parent;if(CM_Get_Parent(out parent,node,0)!=0)break;node=parent;}return result.ToArray();}
 class HideJournal {public int version;public string cli;public string[] addedDevices,addedApps,baseline,suspendedDevices;public bool enabled;}
 static string Cli(string cli,List<string> args){foreach(string arg in args)if(arg.IndexOf('"')>=0||arg.IndexOf('\n')>=0||arg.IndexOf('\r')>=0)throw new Exception("Invalid recovery argument");var quoted=new List<string>();foreach(string arg in args)quoted.Add("\""+arg+"\"");var info=new ProcessStartInfo(cli,string.Join(" ",quoted)){UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardOutput=true,RedirectStandardError=true};using(var p=Process.Start(info)){p.StandardInput.Close();var output=p.StandardOutput.ReadToEndAsync();var error=p.StandardError.ReadToEndAsync();if(!p.WaitForExit(8000)){p.Kill();throw new Exception("Recovery timeout");}if(p.ExitCode!=0)throw new Exception("Recovery CLI failed");return output.Result;}}
 static void WatchHide(int parent,string file){
   string original=File.ReadAllText(file);var saved=json.Deserialize<HideJournal>(original);
   string root=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),"Nefarius Software Solutions","HidHide");
   if(saved.version!=1||(saved.cli!=Path.Combine(root,"HidHideCLI.exe")&&saved.cli!=Path.Combine(root,"x64","HidHideCLI.exe")))throw new Exception("Invalid recovery tool");
   foreach(string d in saved.addedDevices)if(!Regex.IsMatch(d,@"^(HID|USB)\\VID_3537&PID_",RegexOptions.IgnoreCase))throw new Exception("Invalid recovery device");
   Process owner;try{owner=Process.GetProcessById(parent);}catch{owner=null;}
   Console.WriteLine("READY");Console.Out.Flush();
   while(owner!=null){try{if(owner.WaitForExit(300))break;}catch{break;}if(!File.Exists(file)||File.ReadAllText(file)!=original)return;}
   for(int retry=0;retry<20;retry++){try{
     if(!File.Exists(file)||File.ReadAllText(file)!=original)return;
     string snapshot=Cli(saved.cli,new List<string>{"--cloak-state","--inv-state","--dev-list","--cancel"});
     var args=new List<string>();foreach(string d in saved.addedDevices){args.Add("--dev-unhide");args.Add(d);}foreach(string a in saved.addedApps){args.Add("--app-unreg");args.Add(a);}
     var remaining=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(Match m in Regex.Matches(snapshot,"--dev-hide \"([^\"\\r\\n]+)\""))remaining.Add(m.Groups[1].Value);
     remaining.ExceptWith(saved.addedDevices);var suspended=saved.suspendedDevices??new string[0];var retained=new HashSet<string>(saved.baseline,StringComparer.OrdinalIgnoreCase);foreach(string d in suspended){if(!retained.Contains(d))throw new Exception("Invalid saved inactive rule");}retained.ExceptWith(suspended);
     bool changed=!remaining.IsSubsetOf(retained),active=snapshot.Contains("--cloak-on"),inverse=snapshot.Contains("--inv-on");
     if(saved.enabled&&!changed&&!inverse)args.Add("--cloak-off");
     if(args.Count>0)Cli(saved.cli,args);
     if(suspended.Length>0){if(active&&(changed||inverse))throw new Exception("Another app owns active hiding changes");if(active&&!args.Contains("--cloak-off"))Cli(saved.cli,new List<string>{"--cloak-off"});var restore=new List<string>();foreach(string d in suspended){restore.Add("--dev-hide");restore.Add(d);}Cli(saved.cli,restore);}
     File.Delete(file);return;
   }catch{Thread.Sleep(500);}}
 }
 static void Main(string[] args){if(args.Length==2&&args[0]=="--source-identity"){try{var caps=Identity(uint.Parse(args[1]));Console.WriteLine("{\"vendor\":"+caps.vendor+",\"product\":"+caps.product+"}");}catch{Environment.ExitCode=1;}return;}if(args.Length==2&&args[0]=="--device-parents"){try{Console.WriteLine(json.Serialize(DeviceParents(args[1])));}catch{Environment.ExitCode=1;}return;}if(args.Length==3&&args[0]=="--hidhide-watch"){try{WatchHide(int.Parse(args[1]),args[2]);}catch{Environment.ExitCode=1;}return;}if(args.Length==1&&(args[0]=="--sources"||args[0]=="--detect-source")){bool detect=args[0]=="--detect-source";var min=new int[4,4];var max=new int[4,4];var seen=new bool[4];var last=new Pad[4];var clock=Stopwatch.StartNew();do{for(uint i=0;i<4;i++){State sample;if(XInputGetState(i,out sample)!=0)continue;int[] axes={sample.pad.lx,sample.pad.ly,sample.pad.rx,sample.pad.ry};for(int a=0;a<4;a++){if(!seen[i])min[i,a]=max[i,a]=axes[a];else{min[i,a]=Math.Min(min[i,a],axes[a]);max[i,a]=Math.Max(max[i,a],axes[a]);}}seen[i]=true;last[i]=sample.pad;}if(detect)Thread.Sleep(8);}while(detect&&clock.ElapsedMilliseconds<5000);var rows=new List<string>();for(int i=0;i<4;i++)if(seen[i]){int span=0;for(int a=0;a<4;a++)span=Math.Max(span,max[i,a]-min[i,a]);rows.Add("{\"slot\":"+i+",\"lx\":"+last[i].lx+",\"ly\":"+last[i].ly+",\"rx\":"+last[i].rx+",\"ry\":"+last[i].ry+",\"span\":"+span+"}");}Console.WriteLine("["+string.Join(",",rows)+"]");return;}if(args.Length==3&&args[0]=="--release"){foreach(string value in args[1].Split(',')){int k;if(int.TryParse(value,out k)&&k>0&&k<256)try{Key(k,false);}catch{Environment.ExitCode=1;}}foreach(string value in args[2].Split(',')){int k;if(int.TryParse(value,out k)&&k>=200&&k<=204)try{Mouse(k,false);}catch{Environment.ExitCode=1;}}return;}if(args.Length==1&&args[0]=="--selftest"){var p=new Pad{buttons=4096,lt=133,rt=144,lx=-12345,ly=23456,rx=32767,ry=-32768};var same=Mix(p,new Command());if(!same.Equals(p)||Marshal.SizeOf(typeof(Pad))!=12||Marshal.SizeOf(typeof(Input))!=40)throw new Exception("Native precision/layout failed");var mixed=Mix(p,new Command{blocked=new[]{9,19,21},codes=new[]{10,20,24}});if(mixed.buttons!=8192||mixed.lt!=0||mixed.rt!=255||mixed.ly!=0||mixed.lx!=32767||mixed.rx!=32767||mixed.ry!=-32768)throw new Exception("Native merge failed");if(Marshal.SizeOf(typeof(CapsEx))!=32||!PhysicalIdentity(new CapsEx{vendor=0x3537,product=0x10c5},0x3537,0x10c5)||PhysicalIdentity(new CapsEx{vendor=0x045e,product=0x028e},0x3537,0x10c5)||PhysicalIdentity(new CapsEx{vendor=0x3537,product=0x103d},0x3537,0x10c5))throw new Exception("Source identity guard failed");Console.WriteLine("Native virtual host: source identity, precision, layouts and suppression/overlay passed. No driver or input API accessed.");return;}IntPtr client=IntPtr.Zero,target=IntPtr.Zero;bool timer=false;try{client=vigem_alloc();if(client==IntPtr.Zero)throw new Exception("Cannot allocate virtual-controller client.");Check(vigem_connect(client));if(args.Length==1&&args[0]=="--probe"){Console.WriteLine("{\"available\":true}");return;}
 if((args.Length!=3&&args.Length!=4)||args[0]!="--run")throw new Exception("Invalid host command.");uint slot=uint.Parse(args[1]);int hz=int.Parse(args[2]);if(slot>3||(hz!=250&&hz!=1000&&hz!=4000&&hz!=8000))throw new Exception("Invalid source/rate.");State state;if(XInputGetState(slot,out state)!=0)throw new Exception("Selected XInput source is disconnected.");CapsEx sourceIdentity=Identity(slot);ushort product=args.Length==4?ushort.Parse(args[3]):sourceIdentity.product;RequirePhysical(slot,0x3537,product);target=vigem_target_x360_alloc();Check(vigem_target_add(client,target));RequirePhysical(slot,sourceIdentity.vendor,product);
 lastCommand=Stopwatch.GetTimestamp();new Thread(()=>{try{string line;while((line=Console.ReadLine())!=null){if(line.Length>16384)throw new Exception("Oversized command");if(line=="stop")break;var next=json.Deserialize<Command>(line);lock(gate){command=next;commandReceived=true;lastCommand=Stopwatch.GetTimestamp();}}}catch{}finally{stopped=true;}}){IsBackground=true}.Start();
 Console.WriteLine("{\"ready\":true}");timeBeginPeriod(1);timer=true;long nextAt=Stopwatch.GetTimestamp(),lastStats=nextAt,lastIdentity=nextAt;double step=(double)Stopwatch.Frequency/hz;int reports=0;double maxUs=0;Pad previous=new Pad();bool first=true;
 while(!stopped){if(!commandReceived){Thread.Sleep(1);if((Stopwatch.GetTimestamp()-lastCommand)/(double)Stopwatch.Frequency>2)throw new Exception("App did not provide an initial state.");continue;}long now=Stopwatch.GetTimestamp();if((now-lastCommand)/(double)Stopwatch.Frequency>2)throw new Exception("App heartbeat stopped; virtual controller disconnected.");if(now<nextAt){if(hz<=1000)Thread.Sleep(1);else Thread.SpinWait(32);continue;}nextAt=now+(long)step;if(XInputGetState(slot,out state)!=0)throw new Exception("Physical controller disconnected. Re-enable after reconnecting.");if((now-lastIdentity)/(double)Stopwatch.Frequency>=0.1){RequirePhysical(slot,sourceIdentity.vendor,product);lastIdentity=now;}Command c;lock(gate)c=command;Pad pad=Mix(state.pad,c);UpdateKeys(c);if(first||!pad.Equals(previous)){long before=Stopwatch.GetTimestamp();Check(vigem_target_x360_update(client,target,pad));maxUs=Math.Max(maxUs,(Stopwatch.GetTimestamp()-before)*1000000.0/Stopwatch.Frequency);previous=pad;first=false;reports++;}if((now-lastStats)/(double)Stopwatch.Frequency>=1){Console.WriteLine("{\"reports\":"+reports+",\"submitUs\":"+maxUs.ToString("F1",System.Globalization.CultureInfo.InvariantCulture)+"}");reports=0;maxUs=0;lastStats=now;}}
 }catch(Exception e){Console.WriteLine("{\"error\":"+json.Serialize(e.Message)+"}");Environment.ExitCode=1;}finally{foreach(var k in keys)try{Key(k,false);}catch{}foreach(var k in mouse)try{Mouse(k,false);}catch{}if(target!=IntPtr.Zero){try{vigem_target_x360_update(client,target,new Pad());vigem_target_remove(client,target);}catch{}vigem_target_free(target);}if(client!=IntPtr.Zero){try{vigem_disconnect(client);}catch{}vigem_free(client);}if(timer)timeEndPeriod(1);}}
}
